import pytest
from candidate import digitSum


class TestDigitSum(unittest.TestCase):
    def test_empty_string_returns_zero(self):
        self.assertEqual(digitSum(""), 0)

    def test_single_uppercase_letter(self):
        self.assertEqual(digitSum("A"), 65)

    def test_single_lowercase_letter(self):
        self.assertEqual(digitSum("a"), 0)

    def test_only_uppercase_letters(self):
        self.assertEqual(digitSum("ABC"), 65 + 66 + 67)

    def test_only_lowercase_letters(self):
        self.assertEqual(digitSum("abc"), 0)

    def test_mixed_case_string(self):
        self.assertEqual(digitSum("abAB"), 131)

    def test_example_abcCd(self):
        self.assertEqual(digitSum("abcCd"), 67)

    def test_example_helloE(self):
        self.assertEqual(digitSum("helloE"), 69)

    def test_example_woArBld(self):
        self.assertEqual(digitSum("woArBld"), 131)

    def test_example_aAaaaXa(self):
        self.assertEqual(digitSum("aAaaaXa"), 153)

    def test_string_with_digits(self):
        self.assertEqual(digitSum("A1B2C3"), 65 + 66 + 67)

    def test_string_with_special_characters(self):
        self.assertEqual(digitSum("!@#A$%B"), 65 + 66)

    def test_string_with_spaces(self):
        self.assertEqual(digitSum("A B C"), 65 + 66 + 67)

    def test_all_characters_non_uppercase(self):
        self.assertEqual(digitSum("123!@# abc"), 0)

    def test_uppercase_and_lowercase_alternating(self):
        self.assertEqual(digitSum("aBcDeF"), 66 + 68 + 70)

    def test_single_character_upper_z(self):
        self.assertEqual(digitSum("Z"), 90)

    def test_all_uppercase_a_to_z(self):
        expected = sum(ord(c) for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ")
        self.assertEqual(digitSum("ABCDEFGHIJKLMNOPQRSTUVWXYZ"), expected)

    def test_unicode_uppercase_letters(self):
        self.assertEqual(digitSum("É"), ord("É"))

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            digitSum(None)

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            digitSum(12345)

    def test_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            digitSum(["A", "B"])

    def test_long_string_with_one_uppercase_at_end(self):
        self.assertEqual(digitSum("a" * 100 + "Z"), 90)

    def test_long_string_with_one_uppercase_at_start(self):
        self.assertEqual(digitSum("Z" + "a" * 100), 90)

    def test_repeated_same_uppercase(self):
        self.assertEqual(digitSum("AAAAA"), 65 * 5)

    def test_only_newline_and_tab(self):
        self.assertEqual(digitSum("\n\t\r"), 0)

    def test_uppercase_in_middle_of_sentence(self):
        self.assertEqual(digitSum("hello World"), 87)

    def test_multiple_sentences_with_uppercase(self):
        self.assertEqual(digitSum("Hello World Foo Bar"), 72 + 87 + 70 + 66)


if __name__ == '__main__':
    unittest.main()
